function relatedRoutes(){const choices={'special-events':['musical','listening','screen'],israel:["musical","listening","watch"],watch:["before","israel","screen"],humor:['musical','listening','tribute'],sitemap:['before','map','resources'],home:[],before:['watch','musical','hugo'],after:['ideas','compare','novel'],hugo:['novel','musical','resources'],novel:['compare','characters','quiz'],story:['characters','map','listening'],characters:['map','ideas','quiz'],compare:['novel','musical','screen'],history:['map','novel','ideas'],musical:['special-events','watch','listening'],listening:['musical','screen','after'],screen:['compare','musical','resources'],tribute:['listening','humor','resources'],map:['places','history','characters'],places:['map','recipes','history'],recipes:['places','map','novel'],ideas:['characters','history','quiz'],quiz:['story','musical','ideas'],resources:['hugo','musical','listening'],about:['hugo','history','resources']};const links=(choices[route]||[]).map(p=>lang==='en'&&route==='watch'&&p==='israel'?'musical':p);if(!links.length)return '';return `<aside class="related-section"><div class="wrap"><div class="eyebrow">${t('הדלת הבאה כבר פתוחה','YOUR NEXT DOOR IS OPEN')}</div><h2>${t('בחרו שאלה אחת להמשיך איתה.','Choose one question to follow next.')}</h2><div class="related-grid">${links.map((p,i)=>`<a href="${url(p)}"><span class="related-number">0${i+1}</span><div><h3>${h(labels[p])}</h3><p>${h(pageHints[p])}</p></div>${arrow}</a>`).join('')}</div></div></aside>`}

// Keep both audiences oriented even when arriving directly from search or a shared link.
function audienceWayfinding(){
 const musical=['before','musical','story','listening','screen','watch','special-events','israel'].includes(route);
 const novel=['novel','hugo'].includes(route);
 if(!musical&&!novel&&route!=='compare')return '';
 const links=musical?[['before',t('לפני ההצגה','Before the show')],['musical',t('מדריך השירים','Song guide')],['story',t('עלילת המחזמר','Musical plot')],['special-events',t('קונצרטים וימי שנה','Anniversary concerts')]]:novel?[['novel',t('מלווה קריאה לפרקים','Chapter reading companion')],['hugo',t('ויקטור הוגו והרומן','Victor Hugo & the novel')]]:[['novel',t('בחזרה לספר','Explore the novel')],['musical',t('אל מדריך המחזמר','Explore the musical')]];
 return `<nav class="audience-wayfinding wrap" aria-label="${t('ניווט לפי הספר והמחזמר','Novel and musical navigation')}"><div><strong>${musical?t('מסלול המחזמר','Musical guide'):novel?t('מסלול הספר','Novel guide'):t('מהספר אל הבמה','From novel to stage')}</strong><span>${musical?t('שירים, במה וצפייה. פרטי עלילה נפתחים לבחירה.','Songs, stage and viewing. Plot details open by choice.'):novel?t('הרומן של ויקטור הוגו. קראו לפי המקום שלכם בספר.','Victor Hugo’s novel. Read from your place in the book.'):t('השוואת העיבוד כוללת ספוילרים לבחירה.','Adaptation comparisons contain opt-in spoilers.')}</span></div><ul>${links.map(([p,label])=>`<li><a href="${url(p)}"${p===route?' aria-current="page"':''}>${label}</a></li>`).join('')}<li><a class="journey-switch" href="${url('home')}?interest=${musical?'novel':'musical'}#home-classic-heading">${musical?t('מחפשים את הספר?','Looking for the novel?'):t('מחפשים את המחזמר?','Looking for the musical?')}</a></li></ul></nav>`
}

