// Ordinary links are rendered up front: discovery must not depend on opening a JavaScript menu.
function guideDirectory(){return `<details class="footer-directory"><summary>${t('לגלות את המדריך','Explore the guide')}</summary><nav aria-label="${t('חלקי המדריך','Guide sections')}" class="footer-directory-groups">${Object.values(navGroups).map(g=>`<section><h2>${h(g.title)}</h2><ul>${g.pages.map(p=>`<li><a href="${url(p)}"${route===p?' aria-current="page"':''}>${h(labels[p])}</a></li>`).join('')}</ul></section>`).join('')}</nav></details>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-main"><div><a class="brand" href="${url('home')}">${logo}<span><b class="brand-name" lang="en" dir="ltr">LesMis<span>Notes</span></b><small>${t('עלובי החיים, קצת יותר מקרוב','LES MISÉRABLES, LOOK A LITTLE CLOSER.')}</small></span></a><p>${t('פרויקט מעריצים עצמאי ולא רשמי. אין זיקה או חסות מצד בעלי הזכויות. עלובי החיים והיצירות המוזיקליות שייכים לבעלי הזכויות שלהם. המדריך משלב פרשנות מקורית וציטוטים קצרים שמסומנים ומיוחסים למקור.','An independent, unofficial fan project. Not affiliated with or endorsed by the rights holders. Les Misérables and its music belong to their respective rights holders. This guide combines original commentary with clearly attributed brief quotations.')}</p></div><div class="footer-links"><a href="${url('contact')}">${t('צור קשר ומשוב','Contact & feedback')}</a><a href="${url('sitemap')}">${t('מפת האתר','Site map')}</a><a href="${url('resources')}">${t('עוד אתרים לגלות','More places to explore')}</a><a href="${url('about')}">${t('מקורות וקרדיטים','Sources & credits')}</a><a href="${url('privacy')}">${t('פרטיות ובחירות','Privacy & choices')}</a><a href="${url('terms')}">${t('תנאי שימוש','Terms of use')}</a><button class="text-button" data-action="privacy-open">${t('העדפות פרטיות וקובצי Cookie','Privacy & cookie choices')}</button>${external('https://www.lesmis.com/',t('האתר הרשמי','Official site'))}</div></div>${guideDirectory()}<div class="footer-bottom"><span>${t('פריז, 1832. השאלות עדיין כאן.','PARIS, 1832. THE QUESTIONS ARE STILL HERE.')}</span><span>${t('איור מקורי · מקורות לצד התוכן','ORIGINAL ARTWORK · SOURCES WITH THE CONTENT')}</span></div></div></footer>`}
function pageBreadcrumbs(){return `<nav class="breadcrumb" aria-label="${t('נתיב ניווט','Breadcrumb')}"><ol><li><a href="${url('home')}">${t('בית','Home')}</a></li><li><span aria-current="page">${h(labels[route])}</span></li></ol></nav>`}
function top(title,sub,kicker){return `<section class="page-top"><div class="wrap"><div class="page-top-tools">${route==='novel'?'':pageBreadcrumbs()}${bookmarkControl()}</div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${sub}</p></div></section>`}
function banner(){return `<div class="spoiler-banner"><span>${t('ספוילרים פתוחים: הפרטים כוללים גילויי עלילה והסוף.','Spoilers are on: details include major revelations and the ending.')}</span><button data-action="hide-spoilers">${t('להסתיר שוב','Hide again')}</button></div>`}
function gate(kind){return `<div class="gate"><span class="gate-icon" aria-hidden="true">!</span><div class="eyebrow" style="justify-content:center">${t('רגע לפני שיודעים הכול','BEFORE YOU KNOW EVERYTHING')}</div><h2>${t('מכאן, גם הסוף בפנים.','The ending is in here, too.')}</h2><p>${kind==='compare'?t('הבדלים בין הספר למחזמר חושפים מה השתנה, מה נעלם ומה קורה לדמויות. זה מקום נהדר לחזור אליו אחרי הצפייה.','Comparing the novel and musical reveals what changes, what disappears, and what happens to the characters. A good place to return after watching.'):kind==='characters'?t('מפת הקשרים כוללת זהויות, בחירות וגורלות. פתיחתה מאפשרת גם את פרטי העלילה בשאר המדריך.','The relationship map includes identities, choices and fates. Opening it also enables story details elsewhere in the guide.'):t('המסלול המלא עוקב אחרי שתי המערכות, כולל רגעי המפנה וגורל הדמויות. לא נחשוף אותם עד שתבחרו.','The full journey follows both acts, including turning points and the characters’ fates. Nothing is revealed until you choose.')}</p><div class="button-row"><button class="btn" data-action="enable-spoilers">${t('קראתי. לפתוח את הספוילרים','I understand. Reveal spoilers')}${arrow}</button>${link('listening',t('בינתיים, אל המוזיקה','Take me to the music'),'btn secondary')}</div><p class="safe-note">${t('הבחירה נשמרת בלשונית הזאת בלבד. אפשר להסתיר שוב בכל רגע.','Your choice lasts for this tab’s session. You can hide details again at any time.')}</p></div>`}
let homeJourney='first';
const journeyPaths=[{id:'first',title:{he:'לפני הפעם הראשונה',en:'Before your first show'},intro:{he:'קצת כיוון, בלי לקלקל את ההפתעה. התחילו בהכנה לערב, וקחו רק את הרקע שמתחשק לכם.',en:'A few bearings without spoiling the surprise. Start with the evening itself and take only the background you want.'},time:{he:'כ־10 דקות לטעימה · ההעמקה לבחירתכם',en:'About 10 minutes for a first taste · explore further if you wish'},pages:['before','story','map','musical']},{id:'after',title:{he:'אחרי שהמסך ירד',en:'After the show'},intro:{he:'שיר בראש, שאלה בלב? חוזרים לרגע אחד, משווים דרך אחרת לשיר אותו, וממשיכים לשיחה.',en:'A song in your head, a question still open? Return to a moment, hear another interpretation and keep the conversation going.'},time:{he:'כ־15 דקות לפתיחה · לא כולל צפייה בסרטונים',en:'About 15 minutes to get started · video time is extra'},pages:['after','listening','compare','ideas']},{id:'book',title:{he:'מהספר אל הבמה',en:'From page to stage'},intro:{he:'פוגשים את הוגו, מרעננים את הזיכרון, ואז רואים איך רומן רחב יריעה נעשה ערב של מוזיקה.',en:'Meet Hugo, refresh your memory and explore how a sprawling novel becomes an evening of music.'},time:{he:'כ־15 דקות למבט ראשון · כולל אירועים מהרומן',en:'About 15 minutes for an overview · includes events from the novel'},pages:['hugo','novel','compare','musical']},{id:'voices',title:{he:'בעקבות הביצועים',en:'Follow the performances'},intro:{he:'אותו שיר יכול לפגוש אתכם אחרת אצל כל מבצע. מתחילים בהשוואה מודרכת, ומרחיבים את האוזניים מעבר לבמה.',en:'The same song can reach you differently through each performer. Start with a guided comparison, then listen beyond the stage.'},time:{he:'כ־10 דקות להתמצאות · אורך ההאזנה לבחירתכם',en:'About 10 minutes to find your way · listen for as long as you like'},pages:['listening','musical','screen','after']},{id:'play',title:{he:'ללמוד דרך משחק',en:'Learn through play'},intro:{he:'שאלה טובה, קשר שלא שמתם לב אליו, מקום שפתאום מסתדר בראש. אפשר להתחיל בחידון קצר ולהמשיך בעקבות הסקרנות.',en:'A good question, a connection you missed, a place that suddenly makes sense. Try a short quiz and follow your curiosity from there.'},time:{he:'כ־10 דקות לסיבוב קצר · אפשר גם 5 שאלות בלבד',en:'About 10 minutes for a short round · a five-question quiz is available'},pages:['quiz','characters','map','history']}];
function journeyCards(){const d=journeyPaths.find(x=>x.id===homeJourney)||journeyPaths[0];return `<div class="journey-intro" aria-live="polite"><h3>${h(d.title)}</h3><p>${h(d.intro)}</p><small>${h(d.time)}</small></div><div class="journey-cards">${d.pages.map((p,i)=>`<a href="${d.id==='voices'&&p==='listening'?galleryHref('_6nTyXcmgLc'):url(p)}" data-enter-journey="${d.id}"><span class="journey-step">0${i+1}</span><div><h3>${h(labels[p])}</h3><p>${h(pageHints[p])}</p></div>${arrow}</a>`).join('')}</div>`}
function journeyArrival(method){const j=journeyPaths.find(x=>x.id===history.state?.lesmisJourney);if(!j)return;const step=j.pages.indexOf(route)+1;if(step<1)return;A.track('journey_step',{journey_id:j.id,step_index:step,entry_method:method});if(step===j.pages.length)A.track('journey_complete',{journey_id:j.id,step_index:step})}
function journeyContinuation(){const d=journeyPaths.find(x=>x.id===history.state?.lesmisJourney);if(!d)return '';const i=d.pages.indexOf(route);if(i<0)return '';const next=d.pages[i+1];return `<aside class="journey-continuation" aria-label="${t('מסלול הביקור שבחרתם','Your chosen visit path')}"><div class="wrap journey-continuation-inner"><div class="journey-current"><span>${t('תחנה','STOP')} <bdi dir="ltr">${i+1} / ${d.pages.length}</bdi></span><b>${h(d.title)}</b>${d.prompts?`<small>${h(d.prompts[i])}</small>`:''}</div>${next?`<a class="journey-next" href="${url(next)}"><span>${t('התחנה הבאה','NEXT STOP')}</span><b>${h(labels[next])}</b>${arrow}</a>`:`<p>${t('הגעתם לסוף המסלול. כל המדריך פתוח להמשך הגילוי.','You’ve reached the end of this path. Keep exploring the guide.')}</p>`}<div class="journey-options"><a class="text-button journey-switch" href="${url('home')}${d.interest?'?interest='+d.interest:''}#home-classic-heading">${t('לשנות כיוון','Switch path')}</a><button class="text-button" data-action="journey-exit">${t('לגלוש בחופשיות','Browse freely')} <span aria-hidden="true">×</span></button></div></div></aside>`}
function homeJourneyChooser(){return `<section class="section home-journeys" aria-labelledby="home-journeys-heading"><div class="section-head"><div><div class="eyebrow">${t('חמש דרכים להיכנס, בלי ללכת לאיבוד','FIVE WAYS IN, WITHOUT GETTING LOST')}</div><h2 id="home-journeys-heading">${t('מה הביא אתכם לכאן?','What brings you here?')}</h2></div><p>${t('כל מסלול מחבר ארבעה דפים. בחרו לפי מה שמעניין אתכם כרגע; אפשר לדלג בין התחנות.','Each path connects four pages. Choose what interests you now and skip between stops whenever you like.')}</p></div><div class="journey-choices" role="group" aria-label="${t('בחירת מסע','Choose a journey')}">${journeyPaths.filter(j=>!j.interest).map(j=>`<button data-home-journey="${j.id}" aria-pressed="${homeJourney===j.id}" class="${homeJourney===j.id?'active':''}">${h(j.title)}</button>`).join('')}</div><div id="home-journey-content">${journeyCards()}</div><div class="home-discovery-link"><p>${t('רוצים לראות את התמונה כולה?','Want to see the whole picture?')}</p>${link('sitemap',t('מפת האתר: כל החלקים, בלי לפתוח הכול בבת אחת','Site map: every part, without opening everything at once'),'text-link')}</div></section>`}
function sitemapPage(){return top(t('כל חלקי המדריך.','Explore the guide.'),t('הספר, המחזמר, האנשים, המקומות והשאלות. בחרו לפי מה שמעניין אתכם עכשיו; סימוני הספוילרים יעזרו לבחור כמה לפתוח.','The book, the musical, the people, the places and the questions. Choose what interests you now; spoiler labels help you decide how far to go.'),t('18 / למצוא את הדרך','18 / FIND YOUR WAY'))+`<div class="wrap section"><div class="sitemap-start"><div><h2>${t('לא בטוחים מאיפה להתחיל?','Not sure where to begin?')}</h2><p>${t('בחרו בדף הבית את המחזמר או את הסיפור. כאן תמצאו את כל הדפים, ותוכלו לעבור ביניהם בחופשיות.','Start with the musical or the story on the home page. Find every page here and move freely between them.')}</p></div>${link('home',t('לבחירת מסע','Choose a journey'))}</div><div class="sitemap-groups">${Object.entries(navGroups).map(([id,g],i)=>`<section><div class="sitemap-group-title"><span>0${i+1}</span><h2>${h(g.title)}</h2></div><ul>${g.pages.filter(p=>p!=='sitemap').map(p=>`<li><a href="${url(p)}"><h3>${h(labels[p])}</h3><p>${h(pageHints[p])}</p><small>${p==='novel'?t('התקצירים כוללים פרטי עלילה; הרענון המלא לבחירה','SUMMARIES INCLUDE PLOT; FULL RECAP IS OPTIONAL'):['after','quiz','story','characters','compare','ideas'].includes(p)?t('פרטי עלילה באישור','PLOT DETAILS BY CONSENT'):t('אפשר להתחיל בלי לדעת את הסוף','START WITHOUT KNOWING THE ENDING')}</small>${arrow}</a></li>`).join('')}</ul></section>`).join('')}</div>${profileDirectory()}<div class="sitemap-foot"><div><h3>${t('המקורות והבחירות מאחורי המדריך','The sources and choices behind the guide')}</h3><p>${t('פרויקט מעריצים עצמאי. כאן נמצאים הקרדיטים, מדיניות הפרטיות והמקורות.','An independent fan project. Find credits, privacy information and research sources here.')}</p></div><div class="button-row">${link('about',t('מאחורי הקלעים','Behind the guide'),'btn secondary')}${link('privacy',t('פרטיות ובחירות','Privacy & choices'),'btn secondary')}${link('terms',t('תנאי שימוש','Terms of use'),'btn secondary')}</div></div></div>`}
const interestPaths=[
{id:'novel',journeyId:'interest-novel',title:{he:'אני כאן בשביל הספר',en:'I’m here for the novel'},kind:{he:'לקרוא עם הוגו',en:'READ WITH HUGO'},body:{he:'לקרוא בקצב שלכם, להכיר את הדמויות ולהבין את העולם של הוגו.',en:'Read at your own pace. Get to know the people and the world Hugo built.'},pages:['novel','characters','map','hugo'],prompts:[{he:'בחרו חלק וספר, וקראו את תקצירי הפרקים לפי המקום שלכם.',en:'Choose your Part and Book, then follow the chapters at your own pace.'},{he:'הכירו את הדמויות ועקבו אחר קשרי המשפחה והעימותים.',en:'Meet the characters and trace their family ties and conflicts.'},{he:'מצאו את הרחובות, הגנים והעיירות שהוגו מזכיר.',en:'Find the streets, gardens and towns Hugo names.'},{he:'קראו על הכתיבה, החברה והרעיונות שמאחורי הרומן.',en:'Explore the writing, society and ideas behind the novel.'}]},
{id:'musical',journeyId:'interest-musical',title:{he:'אני כאן בשביל המחזמר',en:'I’m here for the musical'},kind:{he:'להכיר ולשמוע',en:'WATCH & LISTEN'},body:{he:'להיכנס דרך השירים, לגלות ביצועים ולהתכונן לערב בתיאטרון.',en:'Start with the songs, discover performances and get ready for a night at the theatre.'},pages:['before','musical','listening','screen'],prompts:[{he:'קבלו רקע קצר לדמויות, לסיפור ולערב בתיאטרון.',en:'Get a short introduction to the characters, story and theatre visit.'},{he:'עקבו אחר השירים בשתי המערכות, או בחרו שיר להעמקה.',en:'Follow the songs through both acts, or choose one to explore.'},{he:'השוו מבצעים ושמעו מה מורי הפיתוח הקולי מציעים לבדוק.',en:'Compare performers and explore the vocal coaches’ listening guides.'},{he:'בחרו סרט, סדרה או קונצרט מצולם להמשך הצפייה.',en:'Choose a film, series or filmed concert to watch next.'}]},
{id:'both',journeyId:'interest-both',title:{he:'גם וגם',en:'Both'},kind:{he:'מהעמוד אל הבמה',en:'FROM PAGE TO STAGE'},body:{he:'מה הוגו כתב, מה השתנה בעיבוד ואיך השירים מספרים את הסיפור.',en:'Explore what Hugo wrote, what the adaptation changed and how the songs tell the story.'},pages:['hugo','story','compare','musical'],prompts:[{he:'התחילו ברומן ובשאלות שהעסיקו את הוגו.',en:'Begin with the novel and the questions that occupied Hugo.'},{he:'התמצאו בעלילת המחזמר בשמונה תחנות.',en:'Find your way through the musical in eight story chapters.'},{he:'השוו דמויות, אירועים והכרעות שהשתנו בדרך לבמה.',en:'Compare the characters, events and decisions changed for the stage.'},{he:'חזרו לשירים ולביצועים עם ההבדלים האלה בראש.',en:'Return to the songs and performances with those differences in mind.'}]}
];
for(const d of interestPaths)journeyPaths.push({id:d.journeyId,title:{he:d.id==='novel'?'הסיפור והספר':d.id==='musical'?'מסלול המחזמר':'מהספר אל הבמה',en:d.id==='novel'?'Story & novel':d.id==='musical'?'The musical':'Page to stage'},intro:d.body,pages:d.pages,interest:d.id,prompts:d.prompts});
let homeInterest='';
function selectedInterest(){const q=new URLSearchParams(location.search||'').get('interest');if(q!==null){const selected=interestPaths.find(d=>d.id===q)||null;homeInterest=selected?.id||'';return selected}return interestPaths.find(d=>d.id===homeInterest)||interestPaths.find(d=>d.journeyId===lastJourney()?.id)||null}
function interestIcon(id){return `<svg class="interest-icon" viewBox="0 0 64 54" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2">${id==='novel'?'<path d="M32 12C24 6 12 7 5 10v34c9-4 18-3 27 3 9-6 18-7 27-3V10c-7-3-19-4-27 2v35"/><path d="M12 17c5-1 10 0 14 2m-14 6c5-1 10 0 14 2m12-8c4-2 9-3 14-2m-14 10c4-2 9-3 14-2"/>':id==='musical'?'<path d="M5 5h54v43H5zM13 5c0 14-1 24-8 29m46-29c0 14 1 24 8 29M5 48h54M28 38V17l15-3v19"/><ellipse cx="23" cy="39" rx="5" ry="3"/><ellipse cx="38" cy="34" rx="5" ry="3"/>':'<path d="M5 12h18l9 6 9-6h18v33H41l-9 5-9-5H5zM32 18v32M14 20v17m5-14v14m27-17v17m5-14v14M23 6l9-4 9 4"/>'}</svg>`}
function interestPlan(d){if(!d)return '';const musical=d.id==='musical',saved=savedReading(),resume=!musical&&saved&&['part','book','chapter'].includes(saved.kind);const primary=musical?url('musical')+'?focus=song%3Awork-song&view=journey':resume?readingHref(saved.kind,saved.key,lang,saved.view,saved.act,saved.watch,saved.essays==='all'):url('novel');const options=musical?[['before',t('הולכים להצגה?','Going to the show?'),t('רקע קצר, בלי לגלות את הסוף.','A short, spoiler-safe introduction.')],['listening',t('למצוא ביצוע שאוהבים','Find a performance you love'),t('שירים, מבצעים ופרשנויות לבחירה.','Songs, singers and interpretations to explore.')],['screen',t('לבחור הקלטה או סרט','Choose a recording or film'),t('עזרה בבחירת הגרסה הבאה לצפייה.','Find the right version for your next watch.')]]:[['characters',t('להכיר את הדמויות','Meet the characters'),t('מי קשור למי, בלי לפתוח את הסוף.','Who is connected to whom, without revealing the ending.')],['map',t('לעקוב אחר המקומות','Follow the places'),t('הרחובות והמסעות מקבלים צורה.','Put the streets and journeys on the map.')],['hugo',t('להבין את העולם של הוגו','Explore Hugo’s world'),t('הרעיונות והרקע שמאחורי הרומן.','The ideas and context behind the novel.')]];return `<section class="interest-plan audience-plan audience-${musical?'musical':'story'}" id="interest-plan" aria-labelledby="interest-plan-title"><div class="audience-lead"><div><span class="eyebrow">${musical?t('המחזמר · מתחילים כאן','THE MUSICAL · START HERE'):t('הסיפור והספר · מתחילים כאן','STORY & NOVEL · START HERE')}</span><h3 id="interest-plan-title" tabindex="-1">${musical?t('לתת לשירים להוביל.','Let the songs lead.'):t('הסיפור, בקצב שלכם.','The story, at your pace.')}</h3><p>${musical?t('מסע צפייה משיר לשיר, לפי סדר המחזמר. פותחים פרטי עלילה רק כשתבחרו.','A viewing journey in the musical’s story order. Plot details open only when you choose.'):t('מדריך קריאה שמלווה אתכם פרק־פרק. בוחרים את המקום שלכם בספר, ומתקדמים ממנו.','A chapter-by-chapter companion. Choose where you are in the novel and take it from there.')}</p><a class="btn interest-start ${musical?'interest-watch-start':''}" href="${primary}" ${musical||resume?'data-insight-link':'data-enter-journey="interest-novel"'}>${musical?t('לצפות בסיפור דרך השירים','Watch the story through the songs'):resume?t('להמשיך מהמקום שלי','Continue where I left off'):t('לפתוח את מדריך הקריאה','Open the chapter companion')}${arrow}</a><p class="audience-reassurance">${musical?t('קליפים נבחרים · ללא הפעלה אוטומטית','Selected clips · no autoplay'):resume?h(readingName(saved)):t('התקצירים חושפים את אירועי הפרק שבחרתם בלבד.','Chapter summaries reveal the events of your selected chapter.')}</p></div>${interestIcon(musical?'musical':'novel')}</div><div class="audience-options"><h4>${t('מה מתחשק לכם עכשיו?','What would you like next?')}</h4><div class="audience-option-grid">${options.map(([page,title,body])=>`<a href="${url(page)}"><b>${title}</b><span>${body}</span>${arrow}</a>`).join('')}</div></div><div class="audience-foot">${musical?`<a href="${url('special-events')}">${t('אירועים מיוחדים וחגיגות','Special events & celebrations')}</a>`:`<a href="${url('history')}">${t('ההיסטוריה שמאחורי הסיפור','The history behind the story')}</a>`}<a href="${url('compare')}">${t('סקרנים לגבי העיבוד? ספר מול במה','Curious about the adaptation? Book vs. stage')}</a></div></section>`}
function homeClassicPaths(){const selected=selectedInterest(),visible=interestPaths.filter(d=>d.id!=='both').reverse();return `<section class="section home-classic-paths dual-journeys" aria-labelledby="home-classic-heading"><div class="section-head"><div><div class="eyebrow">${t('שתי דרכים להיכנס','TWO WAYS IN')}</div><h2 id="home-classic-heading" tabindex="-1">${t('מה מביא אתכם לכאן?','What brings you here?')}</h2></div><p>${t('בחרו את מה שאתם אוהבים. אפשר לעבור בכל רגע.','Start with what you love. Switch whenever you like.')}</p></div><div class="path-grid">${visible.map((d,i)=>`<a class="path-card" data-interest="${d.id}" href="${d.id==='musical'?url('musical')+'?focus=song%3Awork-song&view=journey':url('novel')}" aria-current="${selected?.id===d.id?'true':'false'}" aria-controls="interest-plan-slot"><div class="path-meta"><span class="path-kind">${h(d.kind)}</span>${interestIcon(d.id)}</div><h3>${h(d.title)}</h3><p>${h(d.body)}</p><div class="card-end"><span>${selected?.id===d.id?t('כאן אתם עכשיו','You’re here'):t('זה בשבילי','This is for me')}</span>${arrow}</div></a>`).join('')}</div><div id="interest-plan-slot" aria-live="polite">${interestPlan(selected?.id==='both'?interestPaths[0]:selected)}</div><p class="audience-shared"><a href="${url('sitemap')}">${t('כבר מכירים? לכל חלקי המדריך','Know your way around? Explore the full guide')}</a></p></section>`}

let pendingBookmark=null;
const bookmarkPages=Object.keys(labels).filter(x=>!['home','about','terms','privacy','sitemap'].includes(x));
function savedBookmarks(){if(!P.allowed('functional'))return [];try{const list=JSON.parse(getStored('barricade-bookmarks')||'[]');return Array.isArray(list)?[...new Set(list.filter(x=>bookmarkPages.includes(x)))]:[]}catch{return []}}
function bookmarkControl(){if(!bookmarkPages.includes(route))return '';const marked=savedBookmarks().includes(route);return `<div class="wrap page-utility"><button class="bookmark-control ${marked?'saved':''}" data-action="bookmark-toggle" aria-pressed="${marked}"><svg viewBox="0 0 16 20" aria-hidden="true"><path d="M2 1h12v17l-6-4-6 4z"/></svg><span>${marked?t('נשמר בדפים שלי','Saved in my pages'):t('לשמור לפעם הבאה','Save for another visit')}</span></button></div>`}
function toggleBookmark(page){if(!P.allowed('functional')||!bookmarkPages.includes(page))return;let items=savedBookmarks();items=items.includes(page)?items.filter(x=>x!==page):[...items,page];save('barricade-bookmarks',JSON.stringify(items));A.track('bookmark_change',{content_id:page,bookmark_action:items.includes(page)?'add':'remove'});}
function lastJourney(){if(!P.allowed('functional'))return null;try{const x=JSON.parse(getStored('barricade-last-journey')||'null');const d=journeyPaths.find(j=>j.id===x?.id);return d?.pages.includes(x.route)?{...x,journey:d}:null}catch{return null}}
function rememberJourney(){if(!P.allowed('functional'))return;const d=journeyPaths.find(x=>x.id===history.state?.lesmisJourney);if(!d?.pages.includes(route))return;const old=lastJourney();if(old?.id!==d.id||old?.route!==route)save('barricade-last-journey',JSON.stringify({id:d.id,route,updatedAt:Date.now()}))}
function homeMemory(){if(!P.allowed('functional'))return '';initQuiz();const r=savedReading(),j=lastJourney(),bookmarks=savedBookmarks(),q=quizRun&&!quizRun.finished?quizRun:null;if(!r&&!j&&!bookmarks.length&&!q)return '';return `<section class="home-memory" aria-labelledby="home-memory-title"><div class="home-memory-heading"><div><div class="eyebrow">${t('ברוכים השבים','WELCOME BACK')}</div><h2 id="home-memory-title">${t('המסע שלכם מחכה.','Your journey is waiting.')}</h2></div><button class="text-button" data-action="privacy-open">${t('ניהול הזכירה','Manage remembering')}</button></div><div class="memory-resume-grid">${r?`<a href="${readingHref(r.kind,r.key,lang,r.view,r.act,r.watch,r.essays==='all')}" data-insight-link><span>${t('להמשיך בדיוק מהמקום שלכם','CONTINUE WHERE YOU LEFT OFF')}</span><b>${h(readingName(r))}</b><small>${['part','book','chapter'].includes(r.kind)?t('כולל אירועי היחידה שנבחרה','Includes the selected reading unit’s events'):t('בחירת הספוילרים נשארת שלכם','Your spoiler choice still applies')}</small>${arrow}</a>`:''}${j?`<a href="${url(j.route)}" data-resume-journey="${j.id}"><span>${h(j.journey.title)}</span><b>${t('לחזור אל','Return to')} ${h(labels[j.route])}</b><small>${t('תחנה','Stop')} ${j.journey.pages.indexOf(j.route)+1} / ${j.journey.pages.length} · ${t('הספוילרים נשארים בשליטתכם','Spoilers stay under your control')}</small>${arrow}</a>`:''}${q?`<a href="${url('quiz')}"><span>${t('החידון שלכם מחכה','Your quiz is waiting')}</span><b>${h(R.quiz.trackInfo[q.track].title)} · ${Q.score(q).answered} / ${q.length} ${t('נענו','answered')}</b><small>${t('ממשיכים מהשאלה שנשמרה, אחרי אישור ספוילרים','Resume at the saved question after spoiler consent')}</small>${arrow}</a>`:''}</div>${bookmarks.length?`<details class="saved-pages"><summary>${t('הדפים שלי','My saved pages')} <span>${bookmarks.length}</span></summary><ul>${bookmarks.map(p=>`<li><a href="${url(p)}"><b>${h(labels[p])}</b><small>${h(pageHints[p])}</small>${arrow}</a><button class="text-button" data-remove-bookmark="${p}" aria-label="${esc(t('הסרת סימנייה: ','Remove bookmark: ')+tr(labels[p]))}">×</button></li>`).join('')}</ul></details>`:''}</section>`}

function home(){return `<div class="wrap">${homeMemory()}<div class="home-opening interest-home dual-home"><section class="hero"><div class="hero-copy"><div class="eyebrow">${t('עלובי החיים · הספר והמחזמר','LES MISÉRABLES · THE NOVEL & THE MUSICAL')}</div><h1>${t('סיפור אחד.<br><span>שתי דרכים להתרגש.</span>','One story.<br><span>Two ways to fall in love.</span>')}</h1><p class="lede">${t('השירים שנשארים אתכם. הדמויות שחוזרים אליהן. המדריך שלכם לעלובי החיים, בדרך שמתאימה לכם.','The songs that stay with you. The characters you return to. Find your own way into Les Misérables.')}</p></div><div class="hero-art"><img src="/scene.svg" width="920" height="920" alt="${t('איור של בריקדה תיאטרלית, גגות פריז ודגל אדום מול ירח','Illustration of a theatrical barricade, Paris rooftops and a red flag against the moon')}"></div></section>${homeClassicPaths()}</div></div>`}

function statNote(note){return esc(tr(note));}
function statsSection(){const stats=R.stats||[];return `<div class="section-head"><div><div class="eyebrow">${t('סיפור שחצה גבולות','A STORY THAT CROSSED BORDERS')}</div><h2>${t('קצת פרופורציות.','A little perspective.')}</h2></div><p>${t('דורות של קוראים. אולמות ברחבי העולם.','Generations of readers. Theatres around the world.')}</p></div><div class="stats-grid">${(route==='home'?stats.slice(0,5):stats).map(s=>`<div class="stat"><strong>${esc(s.value)}</strong><h3>${h(s.label)}</h3>${route==='home'?'':`<p>${statNote(s.note)}</p>${sources(s.sourceIds)}`}</div>`).join('')}</div><p class="stats-review-note">${t('נתוני התפוצה: ההפקה הרשמית בלונדון, אוקטובר 2026.','Worldwide reach: official London production, October 2026.')} <a href="${url('about')}#about-provenance">${t('מקורות ותאריכים','Sources and dates')}</a></p>`}
function provenanceNote(){return `<details class="provenance-note" id="about-provenance"><summary>${t('מאין המספרים, ומתי נבדקו?','Where do the figures come from?')}</summary><p>${t('150 מיליון צופים, 57 מדינות, 22 שפות ו־455 ערים הם נתונים מצטברים שמפרסמת ההפקה הרשמית בלונדון. המקור נבדק ב־10 באוקטובר 2026.','The official London production publishes cumulative totals of 150 million viewers, 57 countries, 22 languages and 455 cities. Source checked 10 October 2026.')}</p><p>${t('שמונה פרסי הטוני מתייחסים לשנת 1987; 1862 היא שנת פרסום הרומן; חגיגת 40 השנה בלונדון נערכה ב־8 באוקטובר 2025. גם המקורות ההיסטוריים והקישורים במדף המשאבים נבדקו ב־10 באוקטובר 2026.','The eight Tony Awards belong to 1987; the novel was published in 1862; London celebrated its 40th anniversary on 8 October 2025. These historical sources and the resource shelf links were also reviewed on 10 October 2026.')}</p>${sources(['london-official-about','stat-3','stat-4','stat-5'])}</details>`}
function mapInvitation(){return `<aside class="map-invitation"><div class="map-invitation-art" aria-hidden="true"><svg viewBox="0 0 190 85"><path d="M18 60L60 24 108 55 168 15" fill="none" stroke="currentColor" stroke-width="2" stroke-dasharray="5 6"/><circle cx="18" cy="60" r="7"/><circle cx="60" cy="24" r="7"/><circle cx="108" cy="55" r="7"/><circle cx="168" cy="15" r="9" fill="#ed2939"/></svg></div><div><span class="eyebrow">${t('המקומות מתחברים','CONNECT THE PLACES')}</span><h2>${t('רגע, איפה כל זה קורה?','Wait, where does all this happen?')}</h2><p>${t('מפה גאוגרפית עם תצלומים, ולצדה תשע תחנות סיפור מאוירות ברחבי צרפת ופריז. מוצאים את המקומות, ואז פותחים את התאריכים והחיבורים לדמויות. ספוילרים רק לפי הבחירה שלכם.','A geographic explorer with photographs, plus nine illustrated story stations across France and Paris. Find the places, then follow their dates and character connections. Plot details by choice.')}</p></div>${link('map',t('לפתוח את מפת המסע','Open the interactive story map'),'btn secondary')}</aside>`}
function storyOrientation(){return `<section class="story-orientation"><h2>${t('איפה אנחנו בסיפור הבימתי?','Where are we in the stage story?')}</h2><p>${t('שמונה תחנות לאורך הסיפור הבימתי.','Eight stops through the stage story.')}</p><div>${[['release',t('פרולוג · תחנה 01','Prologue · stop 01'),t('תקופת המאסר מסתיימת; הניסיון להתחיל מחדש רק מתחיל.','A prison term ends; the work of beginning again starts.')],['fantine',t('מערכה ראשונה · תחנות 02–05','Act I · stops 02–05'),t('צרכים שונים ונאמנויות שונות מתכנסים אל אותו משבר.','Different needs and loyalties converge on the same crisis.')],['barricade',t('מערכה שנייה · תחנות 06–08','Act II · stops 06–08'),t('הבחירות של המערכה הראשונה נבחנות במתרס ובמה שבא אחריו.','The first act’s choices are tested at the barricade and in what follows.')]].map(([id,title,body])=>`<button data-jump="story-${id}"><b>${title}</b><span>${body}</span>${arrow}</button>`).join('')}</div></section>`}
function storyFirstLook(){return `<section class="story-first-look" aria-labelledby="story-first-look-heading"><div class="eyebrow">${t('נקודת פתיחה · בלי תפניות ובלי סוף','THE STARTING POINT · NO TWISTS OR ENDING')}</div><h2 id="story-first-look-heading">${t('קודם, להכיר את מה שמונח על הכף.','First, meet what is at stake.')}</h2><p class="story-first-intro">${t('צרפת, 1815. ז׳אן ולז׳אן משתחרר מהכלא, אבל חופש אינו מבטיח מקום בחברה. משם המחזמר נע בין חיים פרטיים לבין הרחוב, עד לפריז של יוני 1832.','France, 1815. Jean Valjean leaves prison, but freedom does not guarantee a place in society. From there, the musical moves between private lives and public streets, reaching Paris in June 1832.')}</p><div class="story-premise-grid"><article><span>01</span><h3>${t('הזדמנות להתחיל מחדש','A chance to begin again')}</h3><p>${t('ולז׳אן מחפש חיים מעבר לזהות של אסיר לשעבר. השאלה אינה רק אם ימצא עבודה ומקום לישון, אלא אם מישהו יהיה מוכן לראות בו אדם שיכול להשתנות.','Valjean looks for a life beyond his identity as an ex-prisoner. The question is not just whether he can find work and shelter, but whether anyone will see a person capable of change.')}</p></article><article><span>02</span><h3>${t('חוק שאמור להישאר יציב','A law meant to stay constant')}</h3><p>${t('ז׳אבר הוא מפקח משטרה שנאחז בחוק ובסדר. כדאי להכיר את המתח הזה מראש: אדם עשוי להשתנות, אבל מה קורה לכללים שנועדו לשפוט אותו?','Javert is an inspector who puts his faith in law and order. Keep this tension in mind: a person may change, but what happens to the rules meant to judge him?')}</p></article><article><span>03</span><h3>${t('עוד חיים נכנסים לתמונה','Other lives enter the picture')}</h3><p>${t('פנטין מנסה לפרנס את בתה; צעירים מחפשים אהבה ואנשים חולמים על חברה צודקת יותר. אין צורך לשנן את כולם. חפשו בכל מפגש מה האדם צריך, ומי מחזיק בכוח לעזור לו.','Fantine tries to support her daughter; young people seek love and others dream of a fairer society. You do not need to memorise everyone. In each encounter, notice what someone needs and who has the power to help.')}</p></article></div><p class="small muted">${t('רוצים להכיר את האנשים לפני שפותחים את העלילה?','Want to meet the people before opening the plot?')} <a href="${url('characters')}#valjean-24601">${t('להכיר את ולז׳אן ואת המספר 24601','Meet Valjean and the number 24601')}</a></p>${sources(['curtain-mti-synopsis','curtain-tour-programme','curtain-june-history'])}</section>`}
function storyPage(){return top(t('עלילת המחזמר,<br>מסצנה לסצנה.','Follow the musical,<br>scene by scene.'),t('משחרורו של ולז׳אן ועד הסיום, בשמונה תחנות. בכל תחנה תמצאו את הדמויות המעורבות, הסצנה הבאה וקישורים לקריאה ולהאזנה.','Eight stages from Valjean’s release to the ending. Each identifies the characters involved and links to related reading and performances.'),t('01 / הסיפור','01 / THE STORY'))+`<div class="wrap section">${storyFirstLook()}${mapInvitation()}<div class="note story-content-note">${t('כדאי לדעת: הסיפור כולל עוני, ניצול, עבודת מין, אלימות ומוות, ובהמשך גם התאבדות. פרטי האירועים נשארים מאחורי אזהרת הספוילרים.','Content note: the story includes poverty, exploitation, sex work, violence and death, and later suicide. Event details remain behind the spoiler warning.')}</div>${!spoiler?gate('story'):banner()+storyOrientation()+`<div class="timeline">${(R.story||[]).map((s,i)=>`<article class="story-chapter" id="story-${esc(s.id)}" tabindex="-1"><span class="chapter-index">${String(i+1).padStart(2,'0')}</span><div class="chapter-meta">${h(s.period)}</div><h2>${h(s.title)}</h2><p class="summary">${profileMentions(s.summary,{ids:s.id==='fantine'?['fantine','cosette']:[]})}</p><details><summary>${t('עוד שכבה: מה קורה כאן באמת?','One layer deeper: what’s happening here?')}</summary><div class="detail-body">${tr(s.detail).split('\n').filter(Boolean).map(p=>`<p>${profileMentions(p,{ids:s.id==='release'?['javert','bishop']:s.id==='paris'?['enjolras','gavroche']:[]})}</p>`).join('')}</div></details>${s.songs?.length?`<div class="song-tags" aria-label="${t('שירים הקשורים לתחנה','Related songs')}">${s.songs.map(song=>`<span lang="en">${esc(song)}</span>`).join('')}</div>`:''}${sources(s.sourceIds)}</article>`).join('')}</div><div class="story-foot"><h3>${t('אחרי הסוף, אפשר לחזור להתחלה.','After the ending, you can return to the beginning.')}</h3><p>${t('מי קיבל הזדמנות להשתנות, וממי נשללה האפשרות?','Who gets a chance to change, and who is denied one?')}</p><div class="button-row">${link('characters',t('לראות את הקשרים','Explore the connections'))}${link('compare',t('ומה קרה בספר?','What happened in the novel?'),'btn secondary')}</div></div>`}</div>`}
function mapCardContext(data,kind){if(!data||(data.spoilerLevel>1&&!spoiler))return '';return `<section class="map-card-context ${kind==='place'?'place-background':'character-depth'}"><h3>${kind==='place'?t('קצת רקע על המקום','A little context for the place'):t('עוד מבט על הדמות','A closer look at the person')}</h3><p>${data.sentences.map(x=>h(x)).join(' ')}</p><div class="source-links">${data.references.filter(ref=>!isTechnicalSource(ref.url)).map(ref=>external(ref.url,tr(ref.label))).join('')}</div></section>`}
function characterCanonNotes(c){return (c.canonNotes||[]).map(n=>`<section class="character-canon-note" aria-labelledby="canon-${esc(n.id)}"><h3 id="canon-${esc(n.id)}">${h(n.title)}</h3>${n.paragraphs.map(p=>`<p>${h(p)}</p>`).join('')}${sources(n.sourceIds)}</section>`).join('')}
function characterPanel(){let c=(R.characters||[]).find(c=>c.id===character)||(R.characters||[])[0];if(!c)return '';character=c.id;return `<article class="char-detail" id="character-detail" tabindex="-1" aria-live="polite"><div class="char-head"><div><div class="eyebrow">${t('דמות מקרוב','IN FOCUS')}</div><h2>${h(c.name)}</h2><span class="pill">${h(c.role)}</span></div><span class="char-mark" aria-hidden="true">${esc(tr(c.name).slice(0,1))}</span></div><p>${h(c.summary)}</p>${window.CharacterProfiles?`<p>${profileLink(c.id,t('לקרוא את הדף המלא של ','Read the full profile of ')+tr(c.name),{className:'text-link'})}</p>`:''}${mapCardContext(c.context,'character')}${characterCanonNotes(c)}<div class="question"><span class="small">${t('שאלה לקחת לצפייה','A question to watch with')}</span><p>${h(c.question)}</p></div><h3>${t('הקשרים שמשנים את הסיפור','Connections that change the story')}</h3><div class="connections">${(c.connections||[]).filter(x=>!x.spoilers||spoiler).map(x=>{const target=R.characters.find(v=>v.id===x.id);return target?`<button class="connection" data-character="${esc(x.id)}"><b>${h(target.name)}</b><small>${h(x.label)}</small>${arrow}</button>`:''}).join('')}</div>${insightBridges('character',c.id)}${sources(c.sourceIds)}</article>`}
function characterNumberFact(){const d=R.safe24601;return d?`<aside class="safe-character-number" id="${esc(d.id)}" tabindex="-1"><h3>${h(d.title)}</h3><p>${h(d.body)}</p>${sources(d.sourceIds)}</aside>`:''}
function safeCharacters(){return `<section class="safe-character-overview" aria-labelledby="safe-characters-title"><div class="eyebrow">${t('להכיר לפני שנכנסים לעלילה','MEET THE PEOPLE BEFORE THE PLOT')}</div><h2 id="safe-characters-title">${t('עשר דמויות. נקודת פתיחה אחת.','Ten characters. A place to begin.')}</h2><p>${t('מי הם, מה הם צריכים ואילו קשרים כדאי להכיר כשנכנסים לסיפור. למעלה מחכה מפת הקשרים; כאן אפשר להכיר כל דמות בנפרד.','Who they are, what they need and the connections that help you enter the story. Explore their connections in the map above, or meet each person individually here.')}</p><nav class="safe-character-index" aria-label="${t('קפיצה לדמות','Jump to a character')}">${R.characters.map(c=>`<a href="#character-intro-${esc(c.id)}">${h(c.name)}</a>`).join('')}</nav><div class="safe-character-grid">${R.characters.map(c=>`<article class="safe-character-card" id="character-intro-${esc(c.id)}" tabindex="-1"><h3>${window.CharacterProfiles?profileLink(c.id,tr(c.name)):h(c.name)}</h3><p>${h(c.safeIntro)}</p>${c.id==='valjean'?characterNumberFact():''}</article>`).join('')}</div><section class="safe-relations" aria-labelledby="safe-relations-title"><h3 id="safe-relations-title">${t('הקשרים הראשונים','The first connections')}</h3><ul>${R.introConnections.map(x=>{const from=R.characters.find(c=>c.id===x.from),to=R.characters.find(c=>c.id===x.to);return `<li><a href="#character-intro-${esc(x.from)}">${h(from.name)}</a> · ${h(x.label)} · <a href="#character-intro-${esc(x.to)}">${h(to.name)}</a></li>`}).join('')}</ul></section><p class="small muted">${t('המקורות החיצוניים כוללים את העלילה המלאה.','External sources include the full story.')}</p>${sources(['novel','mti-synopsis'])}</section>`}
function charactersPage(){return top(t('מפת הקשרים','The relationship map'),t('בחרו דמות כדי לעקוב אחר הקשרים שלה. פתחו את העמוד שלה כדי לקרוא עוד על מקומה בסיפור.','Choose a character to trace their relationships. Open a profile for more on their role in the story.'),t('02 / הדמויות','02 / THE PEOPLE')).replace('class="page-top"','class="page-top characters-top"').replace(bookmarkControl(),'')+`<div class="wrap section characters-page">${relationshipExplorer()}${bookmarkControl()}${profileDirectory()}${window.CharacterProfiles?.discovery(lang,{readerContext:characterProfileContext()})||''}${!spoiler?safeCharacters():banner()+characterNumberFact()+`<section class="character-depth"><h2>${t('הדמויות מקרוב','The people in depth')}</h2><div class="character-layout"><div class="character-picker" aria-label="${t('בחירת דמות','Choose a character')}">${R.characters.map((c,i)=>`<button class="char-button ${c.id===character?'active':''}" data-character="${esc(c.id)}" aria-pressed="${c.id===character}"><span class="initial" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><span><b>${h(c.name)}</b><small>${h(c.role)}</small></span></button>`).join('')}</div><div id="character-panel">${characterPanel()}</div></div></section>`}${mapInvitation()}</div>`}
